    func seedDeepSeek() {
        let known = Set(ingredients.map { $0.name.lowercased() })
        let newItems = Self.deepSeekIngredients.filter { !known.contains($0.name.lowercased()) }
        ingredients.append(contentsOf: newItems)
        saveIngredients()
    }
